/**
 * What every detector scores on OUR studies, and what it costs to run.
 *
 * These are not the numbers a model reports on its own training benchmark.
 * Every variant here went through the same evaluation: 108 colonoscopy studies
 * from this deployment's archive, scored against what the endoscopist's report
 * said. That is why a model can look strong on Kvasir and unremarkable here —
 * the deployed one scores mAP50 0.93 there and finds 77% of studies here.
 *
 * A "variant" is a model AND the settings it was run with. Resolution and the
 * border crop change the result as much as swapping the architecture does —
 * YOLOv5m at 320px scores 58.1% uncropped and 77.4% cropped — so they are rows
 * in their own right rather than a footnote on one.
 *
 * Three things are measured separately because they answer different questions:
 *
 *   sweep   every metric across conf x min-frames, so an operating point can be
 *           moved and the consequences read off rather than guessed at.
 *   noisy   339 frames the review panel called noisy and never called a polyp.
 *           True label is no-polyp, so every detection is wrong by construction.
 *           Kept apart from the study numbers: a study needs 3 frames to be
 *           called positive, so one stray box costs no study — but it does cost
 *           the operator's attention.
 *   speed   measured on the dev laptop by bench-cpu/bench.py, per backend,
 *           because the gap between backends is wider than the gap between
 *           models. Not the server's numbers; see documents/polyp-cpu-inference.md.
 *
 * Generated — see documents/fov-crop-ablation.md. Regenerate rather than
 * hand-edit: a results table maintained by hand drifts into being the numbers
 * somebody wanted.
 */

export interface CurvePoint {
  conf: number; recall: number; fpPerClean: number; alerted: number; clean: number;
}

/** Sensitivity within one slice of the positives — by lesion size or shape. */
export interface Slice { label: string; found: number; total: number; pct: number }

/** One cell of the conf x min-frames grid: the whole confusion matrix there. */
export interface SweepPoint {
  conf: number; minFrames: number;
  tp: number; fn: number; fp: number; tn: number;
  recall: number; specificity: number; precision: number; npv: number;
  f1: number; youden: number;
}

/** False alarms on frames a reviewer called noisy. Every fire here is an error. */
export interface NoisyResult {
  frames: number;
  /** Panel frames arrive already tightly cropped, so the border crop is a no-op
   *  on this set and cannot be judged by it. Measured, not assumed. */
  preCropped: boolean;
  meanConf: number;
  curve: { conf: number; framesFired: number; pct: number }[];
}

export interface SpeedPoint {
  medianMs: number; p90Ms: number; fps: number;
  preMs: number; inferMs: number; postMs: number;
}

export interface ModelResult {
  key: string;
  family: string;
  familyLabel: string;
  imgsz: number;
  crop: boolean;
  label: string;
  deployed: boolean;
  note: string;
  tp: number; fn: number; fp: number; tn: number;
  precision: number; recall: number; f1: number;
  specificity: number; npv: number; youden: number;
  aucMaxConf: number; aucFrames07: number;
  studies: number; positives: number; negatives: number; frames: number;
  bySize: Slice[]; byMorphology: Slice[]; curve: CurvePoint[];
  sweep: SweepPoint[];
  /** backend name -> timing. Absent when the variant was never benchmarked. */
  speed: Record<string, SpeedPoint> | null;
  noisy?: NoisyResult;
}

